package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when an owner supplies an {@code email} that is not a syntactically valid address.
 * {@link ExceptionControllerAdvice} reports it back to the client as a 400 response.
 */
public class InvalidEmailException extends RuntimeException {

    public InvalidEmailException(String message) {
        super(message);
    }

}

