132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        List<String> missingFields = new ArrayList<>();
136	        if (isBlank(ownerFieldsDto.getFirstName())) {
137	            missingFields.add("firstName");
138	        }
139	        if (isBlank(ownerFieldsDto.getLastName())) {
140	            missingFields.add("lastName");
141	        }
142	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
143	        if (isBlank(normalizedAddress)) {
144	            missingFields.add("address");
145	        }
146	        if (isBlank(ownerFieldsDto.getCity())) {
147	            missingFields.add("city");
148	        }
149	        if (isBlank(ownerFieldsDto.getTelephone())) {
150	            missingFields.add("telephone");
151	        }
152	        if (!missingFields.isEmpty()) {
153	            throw new MissingOwnerFieldsException(missingFields);
154	        }
155	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
156	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
157	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
158	            throw new FutureRegistrationDateException(
159	                "registrationDate must not be later than the server date");
160	        }
161	        LocalDate registrationDate = toBusinessDay(
162	            suppliedRegistrationDate != null
163	                ? suppliedRegistrationDate
164	                : LocalDate.now());
165	        long registeredOnDay = this.clinicService.findAllOwners().stream()
166	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
167	            .count();
168	        if (registeredOnDay >= 100) {
169	            throw new DailyRegistrationLimitException(
170	                "100 or more owners have already been registered today");
171	        }
172	        boolean bulkSignupWarning = registeredOnDay > 80;
173	        String city = ownerFieldsDto.getCity();
174	        long ownersInCity = this.clinicService.findAllOwners().stream()
175	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
176	            .count();
177	        if (ownersInCity >= 50) {
178	            throw new CityAtCapacityException(
179	                "the owner's city already contains 50 or more owners");
180	        }
181	        ownerFieldsDto.setAddress(normalizedAddress);
182	        String telephone = toE164(ownerFieldsDto.getTelephone());
183	        ownerFieldsDto.setTelephone(telephone);
184	        String email = normalizeEmail(ownerFieldsDto.getEmail());
185	        ownerFieldsDto.setEmail(email);
186	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
187	        String postcode = ownerFieldsDto.getPostcode();
188	        // Deterministic household id: owners with the same normalized last name and postcode
189	        // share it automatically, regardless of creation order. It is no longer created by the
190	        // 'sharesHousehold' flag; that flag now only bypasses the duplicate block below.
191	        String householdId = householdId(lastName, postcode);
192	        // The household is keyed on (last name, postcode), so its existing members are the
193	        // existing owners with the same computed household id. Both the duplicate block and the
194	        // household size below key off this value.
195	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
196	            .filter(existing -> householdId.equals(
197	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode())))
198	            .toList();
199	        // Household duplicate block: a second owner in an existing household is rejected as a
200	        // household duplicate (409) unless the request opts in via 'sharesHousehold'. Opting in
201	        // only bypasses this block; the owner is then created as a declared household member.
202	        if (!householdMembers.isEmpty()
203	            && !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
204	            throw new DuplicateHouseholdException(
205	                "an owner with the same last name and postcode already exists");
206	        }
207	        // Single, consolidated duplicate check: reject only when the new owner's whole
208	        // derived identity key (telephone|email|householdId) equals an existing owner's.
209	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
210	        boolean identityInUse = this.clinicService.findAllOwners().stream()
211	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
212	                existing.getTelephone(), existing.getEmail(),
213	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode()))));
214	        if (identityInUse) {
215	            throw new DuplicateIdentityException(
216	                "an owner with the same identity key already exists");
217	        }
218	        HttpHeaders headers = new HttpHeaders();
219	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
220	        owner.setRegistrationDate(registrationDate);
221	        owner.setCustomerCode(
222	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
223	        owner.setHouseholdId(householdId);
224	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
225	        owner.setBulkSignupWarning(bulkSignupWarning);
226	        // Household size after this create: existing members plus the owner being created.
227	        owner.setHouseholdSize(householdMembers.size() + 1);
228	        // A declared household member is not a suspected duplicate, and no other create path
229	        // reaches here for a same-household owner, so a created owner is never flagged.
230	        owner.setPossibleDuplicate(false);
231	        owner.setPossibleDuplicateOf(null);
232	        this.clinicService.saveOwner(owner);
233	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
234	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
235	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
236	            ownerDto.getMembershipLevel());
237	        headers.setLocation(UriComponentsBuilder.newInstance()
238	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
239	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
240	    }
