336	    private static boolean isBlank(String value) {
337	        return value == null || value.isBlank();
338	    }
339	
340	    /**
341	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
342	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
343	     * to the effective registration date (whether supplied in the request or defaulted to the server
344	     * date), so every value derived from the registration date sees the adjusted business day.
345	     */
346	    private static LocalDate toBusinessDay(LocalDate date) {
347	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
348	            date = date.plusDays(1);
349	        }
350	        return date;
351	    }
352	
353	    /**
354	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
355	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
356	     * lower-cased so that last names are compared case-insensitively.
357	     */
358	    private static String normalizeHousehold(String value) {
359	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
360	    }
361	
362	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
363	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
364	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
365	
366	    /**
367	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
368	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
369	     * upper-cased, and common street-type abbreviations are expanded token-by-token
370	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
371	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
372	     * used for every address comparison (household-duplicate detection and the shared household id).
373	     */
374	    private static String normalizeAddress(String value) {
375	        if (value == null) {
376	            return "";
377	        }
378	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
379	        if (collapsed.isEmpty()) {
380	            return "";
381	        }
382	        String[] tokens = collapsed.split(" ");
383	        StringBuilder sb = new StringBuilder();
384	        for (int i = 0; i < tokens.length; i++) {
385	            if (i > 0) {
386	                sb.append(' ');
387	            }
388	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
389	        }
390	        return sb.toString();
391	    }
392	
393	    /**
394	     * Derives the stable {@code householdId} shared by all owners in a household: the first 12
395	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. It is a pure,
396	     * deterministic function of the normalized last name and postcode, so every owner that shares
397	     * those values maps to the same identifier regardless of creation order. A {@code null}
398	     * postcode contributes the empty string.
399	     */
400	    private static String householdId(String normalizedLastName, String postcode) {
401	        String key = normalizedLastName + "|" + (postcode == null ? "" : postcode);
402	        return sha256Hex12(key);
403	    }
404	
405	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
406	    private static String sha256Hex12(String s) {
407	        try {
408	            byte[] digest = MessageDigest.getInstance("SHA-256")
409	                .digest(s.getBytes(StandardCharsets.UTF_8));
410	            StringBuilder sb = new StringBuilder(12);
411	            for (int i = 0; i < 6; i++) {
412	                sb.append(String.format("%02x", digest[i]));
413	            }
414	            return sb.toString();
415	        }
416	        catch (NoSuchAlgorithmException e) {
417	            throw new IllegalStateException("SHA-256 not available", e);
418	        }
419	    }
420	
421	    /**
422	     * Builds the {@code customerCode} assigned to a new owner, formatted
423	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
424	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
425	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
426	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
427	     * pure function of the owner's own identity fields.
428	     */
429	    private static String customerCode(String postcode, String telephone, String lastName) {
430	        String region = LocalityDeriver.region(postcode);
431	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
432	            + (lastName == null ? "" : lastName));
433	        return region + "-" + hash8;
434	    }
435	
436	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
437	    private static String sha256Hex8(String s) {
438	        try {
439	            byte[] digest = MessageDigest.getInstance("SHA-256")
440	                .digest(s.getBytes(StandardCharsets.UTF_8));
441	            StringBuilder sb = new StringBuilder(8);
442	            for (int i = 0; i < 4; i++) {
443	                sb.append(String.format("%02X", digest[i]));
444	            }
445	            return sb.toString();
446	        }
447	        catch (NoSuchAlgorithmException e) {
448	            throw new IllegalStateException("SHA-256 not available", e);
449	        }
450	    }
451	
452	    /**
453	     * Counts the existing owners that share the given first name and last name, compared
454	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
455	     * owner currently being created is saved), so it reflects how many namesakes preceded the
456	     * new owner.
457	     */
458	    private int countNamesakes(String firstName, String lastName) {
459	        return (int) this.clinicService.findAllOwners().stream()
460	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
461	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
462	            .count();
463	    }
464	
465	    /**
466	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
467	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
468	     * national one, a single leading {@code '0'} is dropped, and the default country code
469	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
470	     * national number must have the length required by its country code ({@code '+61'} requires 9
471	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
472	     * raised (reported to the client as 400).
473	     */
474	    private static String toE164(String telephone) {
475	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
476	        String digits;
477	        if (cleaned.startsWith("+")) {
478	            digits = cleaned.substring(1);
479	        } else {
480	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
481	            digits = "61" + national;
482	        }
483	        if (!digits.matches("[0-9]{8,15}")) {
484	            throw new InvalidTelephoneException(
485	                "telephone must form a valid E.164 number with 8 to 15 digits");
486	        }
487	        validateNationalLength(digits);
488	        return "+" + digits;
489	    }
490	
491	    /** National-number length required for each supported country code (digits after the code). */
492	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
493	        "61", 9, "1", 10);
494	
495	    /**
496	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
497	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
498	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
499	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
500	     */
501	    private static void validateNationalLength(String digits) {
502	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
503	            String code = entry.getKey();
504	            if (digits.startsWith(code)) {
505	                int nationalLength = digits.length() - code.length();
506	                if (nationalLength != entry.getValue()) {
507	                    throw new InvalidTelephoneException(
508	                        "telephone national number must have " + entry.getValue()
509	                            + " digits for country code +" + code);
510	                }
511	                return;
512	            }
513	        }
514	    }
515	
516	    /**
517	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
518	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
519	     * any 4-digit postcode.
520	     */
521	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
522	        "NSW", new int[] {2000, 2099},
523	        "VIC", new int[] {3000, 3099},
524	        "QLD", new int[] {4000, 4099});
525	
526	    /**
527	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
528	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
529	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
530	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
531	     * no known region accepts any 4-digit postcode. A violation raises an
532	     * {@link InvalidPostcodeException} (reported to the client as 400).
533	     */
534	    private static void validatePostcode(String city, String postcode) {
535	        if (isBlank(postcode)) {
536	            return;
537	        }
538	        if (!postcode.matches("[0-9]{4}")) {
539	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
540	        }
541	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
542	        if (range == null) {
543	            return;
544	        }
545	        int value = Integer.parseInt(postcode);
546	        if (value < range[0] || value > range[1]) {
547	            throw new InvalidPostcodeException(
548	                "postcode is out of range for the owner's city region");
549	        }
550	    }
551	
552	    /**
553	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
554	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
555	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
556	     * stored and returned in canonical form.
557	     */
558	    private static String normalizeEmail(String email) {
559	        if (isBlank(email)) {
560	            return null;
561	        }
562	        String trimmed = email.trim();
563	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
564	            throw new InvalidEmailException("email must be a syntactically valid address");
565	        }
566	        return trimmed.toLowerCase(Locale.ROOT);
567	    }
568	}
